   ["Airborne", "Droplet", "Contact"],
   [("Measles (rubeola)", 0, ["Measles virus stays suspended in the air and needs airborne precautions.", "Droplet precautions do not protect against the airborne measles virus.", "Contact precautions alone do not stop airborne spread."]),
    ("Influenza", 1, ["Influenza is not routinely airborne except during aerosol-generating procedures.", "Influenza spreads by large droplets within about 2 m (6 ft).", "Contact is a minor route; droplet precautions are required."]),
    ("Clostridioides difficile diarrhea", 2, ["C. difficile is not spread through the air.", "C. difficile is not spread by respiratory droplets.", "Spores spread on hands and surfaces, so contact precautions are needed."]),
    ("Mumps", 1, ["Mumps is not airborne.", "Mumps spreads by respiratory droplets and saliva.", "Contact precautions alone are not enough."]),
    ("Pulmonary tuberculosis", 0, ["TB spreads through airborne droplet nuclei.", "A surgical mask and droplet precautions do not filter TB particles.", "TB is not spread by contact."]),
    ("Scabies", 2, ["Scabies mites are not airborne.", "Scabies is not spread by droplets.", "Scabies spreads by skin-to-skin contact and shared linen."])],
   "Remember 'My Chicken Has TB' for airborne (measles, chickenpox, disseminated herpes zoster, TB); droplet for influenza, mumps, pertussis, rubella and meningococcus; contact for C. difficile, MRSA, VRE, scabies and lice.",
